style:
/* 紫垣 —— 淡紫通栏页眉配圆形照片，左侧淡紫窄栏，主栏挂虚线导轨 */

.tw-ziyuan.layout-sidebar.resume-paper.layout-sidebar {
  padding-top: 0;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-header {
  margin: 0 -15mm 6mm;
  padding: 9mm 15mm 6mm;
  background: #eeecf9;
  border: none;
  color: #2c2647;
  align-items: center;
  gap: 7mm;
  print-color-adjust: exact;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-photo {
  order: -1;
  width: 26mm;
  height: 26mm;
  border: 1.4mm solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 0.35mm #d7d1ef;
  object-fit: cover;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.9);
  font-weight: 700;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-name {
  color: #40356f;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.1);
  letter-spacing: 0.08em;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6f678f;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: #5a5182;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 7mm;
  margin-top: 3mm;
  padding-top: 2.6mm;
  border-top: 0.25mm solid #ddd7f0;
  color: #4d456f;
  font-size: calc(var(--paper-base-size) * 0.85);
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-contact__label {
  color: #857cae;
}

/* 窄栏：淡紫底 + 圆角，放在左侧 */
.tw-ziyuan.layout-sidebar.resume-paper .sidebar-layout {
  grid-template-columns: 52mm minmax(0, 1fr);
  column-gap: 8mm;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside {
  grid-column: 1;
  padding: 5mm 4.5mm;
  background: #f5f3fc;
  border-top: none;
  border-radius: 1.6mm;
  print-color-adjust: exact;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-main {
  grid-column: 2;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2mm;
  margin-bottom: 2.6mm;
  padding: 0;
  border: none;
  color: #4a3f7d;
  font-size: calc(var(--paper-base-size) * 0.96);
  letter-spacing: 0.1em;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon {
  display: grid;
  place-items: center;
  width: 4mm;
  height: 4mm;
  color: var(--paper-accent);
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

/* 主栏：虚线导轨 + 标题圆点 */
.tw-ziyuan.layout-sidebar.resume-paper .sidebar-main .paper-section {
  position: relative;
  padding-left: 5.5mm;
  border-left: 0.22mm dashed #d3cdea;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-main .paper-section__title {
  position: relative;
  margin-bottom: 2.8mm;
  padding-bottom: 1.2mm;
  border-bottom: 0.25mm solid #e2ddf2;
  color: #4a3f7d;
  font-size: calc(var(--paper-base-size) * 1.02);
  letter-spacing: 0.08em;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-main .paper-section__title::before {
  content: "";
  position: absolute;
  top: 0.6mm;
  left: -6.9mm;
  width: 2.6mm;
  height: 2.6mm;
  border: 0.3mm solid var(--paper-accent);
  border-radius: 50%;
  background: #fff;
  print-color-adjust: exact;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-main .paper-section__icon {
  display: none;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-section__body {
  color: #3a3358;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-item-title {
  color: #282043;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-item-period {
  color: #7d7599;
  font-size: calc(var(--paper-base-size) * 0.85);
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-item-sub {
  color: #4e4770;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-rich ul,
.tw-ziyuan.layout-sidebar.resume-paper .paper-rich ol {
  margin-top: 0.8mm;
  padding-left: 0;
  list-style: none;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.4mm;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.7em;
  left: 0.4mm;
  width: 1mm;
  height: 1mm;
  border-radius: 50%;
  background: color-mix(in srgb, var(--paper-accent) 55%, #fff);
  print-color-adjust: exact;
}

/* 技能条：窄栏里排成竖向进度条 */
.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 1.8mm;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-skill {
  position: relative;
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__name {
  display: flex;
  justify-content: space-between;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 0.9mm;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i {
  width: 8.4mm;
  height: 1.4mm;
  border-radius: 0;
  background: #e2ddf2;
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-ziyuan.layout-sidebar.resume-paper .sidebar-aside .paper-skill__level {
  position: absolute;
  top: 0;
  right: 0;
  display: inline;
  color: #6d6494;
  font-size: calc(var(--paper-base-size) * 0.78);
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-note__tag {
  color: #40356f;
  font-weight: 600;
}

.tw-ziyuan.layout-sidebar.resume-paper .paper-footer {
  border-top: 0.2mm solid #e6e2f2;
  color: #a49dc0;
}
